use vstd::prelude::*;  

verus! {  
    /// Given a vector `s` of `i8`, return a fresh vector `rev` whose
    /// elements are precisely those of `s` in reverse order.
    ///
    /// Post‐condition:
    ///   1) `rev.len() == s.len()`
    ///   2) for all `k < s.len()`, `rev[k] == s[s.len() - 1 - k]`
    fn reverse(s: Vec<i8>) -> Vec<i8>
        ensures |rev: Vec<i8>| rev.len() == s.len()
            && forall(|k: usize| k < s.len() ==> rev[k] == s[s.len() - 1 - k])
    {
        let n = s.len();
        let mut rev: Vec<i8> = Vec::new();
        let mut i: usize = 0;

        // build rev[0..n) = s[n-1], s[n-2], …, s[0]
        while i < n
            invariant i <= n
            invariant rev.len() == i
            invariant forall(|j: usize| j < i ==> rev[j] == s[n - 1 - j])
            decreases n - i
        {
            rev.push(s[n - 1 - i]);
            i += 1;
        }

        rev
    }
}